package stylegen

import (
	goparser "go/parser"
	"go/token"
	"strings"
	"testing"

	"github.com/gsxhq/gsxui/internal/recipe"
	"github.com/gsxhq/gsxui/registry/canonical/shapes"
)

func TestGenerateAccessorsForASingleRootSlot(t *testing.T) {
	t.Parallel()
	src, err := GenerateAccessors(shapes.Button)
	if err != nil {
		t.Fatalf("GenerateAccessors() error = %v", err)
	}
	got := string(src)
	for _, want := range []string{
		"// Code generated by stylegen; DO NOT EDIT.",
		"package canonical",
		"type buttonRecipe struct",
		"func (r buttonRecipe) Root() string",
		"func (r buttonRecipe) Variant(value string) string",
		"func (r buttonRecipe) Size(value string) string",
	} {
		if !strings.Contains(got, want) {
			t.Errorf("missing %q\nin: %s", want, got)
		}
	}
	if _, err := goparser.ParseFile(token.NewFileSet(), "gen.go", src, 0); err != nil {
		t.Fatalf("generated source does not parse: %v", err)
	}
}

func TestGenerateAccessorsTitleCasesKebabSlots(t *testing.T) {
	t.Parallel()
	shape := recipe.Shape{
		Component: "sidebar",
		Slots: []recipe.Slot{
			{Name: "", Base: true},
			{Name: "menu-button", Base: true, Dimensions: []recipe.Dimension{
				{Name: "size", Default: "default", Values: []string{"default", "lg"}},
			}},
			{Name: "menu-button-tooltip-content", Base: true},
		},
	}
	src, err := GenerateAccessors(shape)
	if err != nil {
		t.Fatalf("GenerateAccessors() error = %v", err)
	}
	got := string(src)
	for _, want := range []string{
		"func (r sidebarRecipe) Root() string",
		"func (r sidebarRecipe) MenuButton() string",
		"func (r sidebarRecipe) MenuButtonSize(value string) string",
		"func (r sidebarRecipe) MenuButtonTooltipContent() string",
	} {
		if !strings.Contains(got, want) {
			t.Errorf("missing %q\nin: %s", want, got)
		}
	}
	if _, err := goparser.ParseFile(token.NewFileSet(), "gen.go", src, 0); err != nil {
		t.Fatalf("generated source does not parse: %v", err)
	}
}

func TestGeneratedAccessorsResolveThroughTheShape(t *testing.T) {
	t.Parallel()
	// The generated bodies delegate to recipe.Component, so an unrecognized
	// value must still fall back to the dimension's declared default.
	c := recipe.Component{Shape: shapes.Button}
	if got, want := c.SlotClass(""), "gsxui-recipe-button"; got != want {
		t.Errorf("SlotClass() = %q, want %q", got, want)
	}
	if got, want := c.SlotValueClass("", "variant", "destructve"),
		"gsxui-recipe-button-variant-default"; got != want {
		t.Errorf("unrecognized value must resolve to the default: got %q, want %q", got, want)
	}
}

// TestGenerateAccessorsRejectsCollidingAccessorNames pins finding 3. Each of
// these shapes passes Shape.Validate and formats without error — format.Source
// parses without type-checking — and then fails at `go build` with "method
// redeclared", after the file is written, naming neither the shape nor the
// slots that collided. Worse, accessorTarget resolves a collided name to the
// FIRST match in declaration order, so resolution binds to the wrong slot well
// before the build ever fails.
func TestGenerateAccessorsRejectsCollidingAccessorNames(t *testing.T) {
	t.Parallel()

	tests := []struct {
		name  string
		shape recipe.Shape
		want  string
	}{{
		name: "root slot and a slot named root",
		shape: recipe.Shape{Component: "sidebar", Slots: []recipe.Slot{
			{Name: "", Base: true},
			{Name: "root", Base: true},
		}},
		want: "reserved",
	}, {
		name: "kebab and camel slot names title-case alike",
		shape: recipe.Shape{Component: "sidebar", Slots: []recipe.Slot{
			{Name: "menu-button", Base: true},
			{Name: "menuButton", Base: true},
		}},
		want: "MenuButton()",
	}, {
		name: "a slot dimension collides with another slot's base accessor",
		shape: recipe.Shape{Component: "sidebar", Slots: []recipe.Slot{
			{Name: "menu", Dimensions: []recipe.Dimension{
				{Name: "button", Default: "default", Values: []string{"default"}},
			}},
			{Name: "menu-button", Base: true},
		}},
		want: "MenuButton()",
	}}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			t.Parallel()
			if err := tt.shape.Validate(); err != nil {
				t.Fatalf("fixture must pass Shape.Validate to pin the gap, got %v", err)
			}
			_, err := GenerateAccessors(tt.shape)
			if err == nil {
				t.Fatal("GenerateAccessors() = nil error, want a collision error")
			}
			if !strings.Contains(err.Error(), tt.want) {
				t.Errorf("GenerateAccessors() error = %q, want it to mention %q", err, tt.want)
			}
			if !strings.Contains(err.Error(), "sidebar") {
				t.Errorf("GenerateAccessors() error = %q, want it to name the shape", err)
			}
		})
	}
}

// TestHelperCallsRejectsCollidingAccessorNames pins the quieter half: the
// binding paths must refuse a shape they cannot resolve unambiguously, rather
// than silently picking the first slot in declaration order.
func TestHelperCallsRejectsCollidingAccessorNames(t *testing.T) {
	t.Parallel()

	shape := recipe.Shape{Component: "sidebar", Slots: []recipe.Slot{
		{Name: "menu", Dimensions: []recipe.Dimension{
			{Name: "button", Default: "default", Values: []string{"default"}},
		}},
		{Name: "menu-button", Base: true},
	}}
	if slot, _, ok := accessorTarget(shape, "MenuButton"); ok && slot != "menu-button" {
		t.Logf("accessorTarget binds MenuButton to slot %q — the wrong one", slot)
	}
	if _, err := HelperCalls("x.gsx", []byte("package p\n"), shape); err == nil {
		t.Fatal("HelperCalls() = nil error, want a collision error before anything binds")
	}
}
